<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Tambah anggota';$error='';
if(osis_admin_is_post()){osis_verify_csrf();$nama=osis_post_string('nama',120);$nis=osis_post_string('nis',40);$kelas=osis_post_string('kelas',60);$hp=osis_post_string('no_hp',30);$email=osis_post_string('email',120);$alamat=osis_post_string('alamat',2000);$username=osis_post_string('username',50);$password=isset($_POST['password'])?(string)$_POST['password']:'';$status=isset($_POST['status'])&&$_POST['status']==='alumni'?'alumni':'aktif';
if($nama===''||$username===''||strlen($password)<8){$error='Nama, username, dan kata sandi minimal 8 karakter wajib diisi.';}elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){$error='Format email tidak valid.';}else{try{$foto=osis_store_uploaded_image(isset($_FILES['foto'])?$_FILES['foto']:null,'anggota');$pdo->beginTransaction();$stmt=$pdo->prepare("INSERT INTO users(nama,username,email,password_hash,role,aktif) VALUES(?,?,?,?, 'anggota',1)");$stmt->execute([$nama,$username,$email?:null,password_hash($password,PASSWORD_DEFAULT)]);$userId=(int)$pdo->lastInsertId();$stmt=$pdo->prepare('INSERT INTO anggota(user_id,nama,nis,kelas,no_hp,email,alamat,status,foto) VALUES(?,?,?,?,?,?,?,?,?)');$stmt->execute([$userId,$nama,$nis?:null,$kelas?:null,$hp?:null,$email?:null,$alamat?:null,$status,$foto]);$pdo->commit();osis_log_activity('Menambahkan anggota: '.$nama);osis_set_flash('success','Anggota dan akun login berhasil dibuat.');osis_redirect('admin/anggota/index.php');}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
