ST['username'])?$_POST['username']:'')?>"></div><div><label for="password">Kata sandi awal <span class="optional">(min. 8 karakter)</span></label><input id="password" name="password" type="password" required minlength="8" autocomplete="new-password"></div></div><label for="foto">Foto profil <span class="optional">JPG, PNG, WEBP · maks. 5 MB</span></label><input id="foto" name="foto" type="file" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/anggota/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan anggota <span>↗</span></button></div></form></div></div>
